'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  let prefix = 0;
  while (prefix < a.length && prefix < b.length && a[prefix] === b[prefix]) {
    prefix++;
  }
  let suffix = 0;
  while (suffix < a.length - prefix && suffix < b.length - prefix &&
         a[a.length - suffix - 1] === b[b.length - suffix - 1]) {
    suffix++;
  }
  const n = a.length - prefix - suffix;
  const m = b.length - prefix - suffix;
  const trace = [];
  let distance = n + m;

  if (n && m) {
    search: for (let d = 0; d <= n + m; d++) {
      // Slot i represents diagonal k = 2 * i - d. Store its furthest x.
      const frontier = new Int32Array(d + 1);
      const previous = trace[d - 1];
      trace.push(frontier);
      for (let i = 0; i <= d; i++) {
        const k = 2 * i - d;
        let x = d === 0 ? 0 :
          (i === 0 || (i < d && previous[i - 1] < previous[i])
            ? previous[i] : previous[i - 1] + 1);
        let y = x - k;
        while (x < n && y < m && a[prefix + x] === b[prefix + y]) {
          x++;
          y++;
        }
        frontier[i] = x;
        if (x >= n && y >= m) {
          distance = d;
          break search;
        }
      }
    }
  }

  const script = new Array(prefix + suffix + (n + m + distance) / 2);
  let write = script.length;
  for (let i = a.length - 1; i >= a.length - suffix; i--) {
    script[--write] = { op: 'equal', line: a[i] };
  }
  let x = n;
  let y = m;
  if (n && m) {
    for (let d = distance; d > 0; d--) {
      const i = (x - y + d) / 2;
      const previous = trace[d - 1];
      const insertion = i === 0 || (i < d && previous[i - 1] < previous[i]);
      const previousK = x - y + (insertion ? 1 : -1);
      const previousX = previous[insertion ? i : i - 1];
      const previousY = previousX - previousK;
      while (x > previousX && y > previousY) {
        script[--write] = { op: 'equal', line: a[prefix + --x] };
        y--;
      }
      if (insertion) {
        script[--write] = { op: 'insert', line: b[prefix + --y] };
      } else {
        script[--write] = { op: 'delete', line: a[prefix + --x] };
      }
    }
    while (x > 0 && y > 0) {
      script[--write] = { op: 'equal', line: a[prefix + --x] };
      y--;
    }
  } else {
    while (y > 0) {
      script[--write] = { op: 'insert', line: b[prefix + --y] };
    }
    while (x > 0) {
      script[--write] = { op: 'delete', line: a[prefix + --x] };
    }
  }
  for (let i = prefix - 1; i >= 0; i--) {
    script[--write] = { op: 'equal', line: a[i] };
  }

  // A shortest path may interleave edits. Stably put deletes first in each gap.
  const inserts = [];
  for (let i = prefix; i < script.length - suffix;) {
    if (script[i].op === 'equal') {
      i++;
      continue;
    }
    let next = i;
    let target = i;
    while (next < script.length - suffix && script[next].op !== 'equal') {
      const entry = script[next++];
      if (entry.op === 'delete') script[target++] = entry;
      else inserts.push(entry);
    }
    for (const entry of inserts) script[target++] = entry;
    inserts.length = 0;
    i = next;
  }
  return script;
}

/**
 * Return unified hunks: [{ oldStart, oldLines, newStart, newLines, lines }].
 * context is a nonnegative integer, default 3. Hunk lines are original strings
 * prefixed with ' ' (equal), '-' (delete), or '+' (insert); remove exactly one
 * prefix to recover a line, even when the original starts with a prefix itself.
 * oldLines counts context + deletes; newLines counts context + inserts.
 * Include up to context unchanged lines before/after each changed region.
 * Merge regions if the intervening unchanged gap is <= 2 * context (their
 * context would touch or overlap). Do not duplicate context in merged hunks.
 * Starts are 1-based, except a zero-line range names the line BEFORE the range:
 * oldLines === 0 uses the preceding old line number (0 for insertion at top),
 * and newLines === 0 uses the preceding new line number (0 for deletion at top).
 * Coordinates refer to the complete original a and result b, not a local hunk.
 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  const script = diffLines(a, b);
  const hunks = [];
  let i = 0;
  let oldCursor = 0;
  let newCursor = 0;
  while (i < script.length) {
    if (script[i].op === 'equal') {
      i++;
      oldCursor++;
      newCursor++;
      continue;
    }
    const start = Math.max(0, i - context);
    const oldFrom = oldCursor - (i - start);
    const newFrom = newCursor - (i - start);
    let end = i;
    while (end < script.length) {
      while (end < script.length && script[end].op !== 'equal') end++;
      const gapStart = end;
      while (end < script.length && script[end].op === 'equal') end++;
      if (end === script.length || end - gapStart > 2 * context) {
        end = gapStart + Math.min(context, end - gapStart);
        break;
      }
    }
    const lines = [];
    let oldLines = 0;
    let newLines = 0;
    for (let j = start; j < end; j++) {
      const { op, line } = script[j];
      if (op !== 'insert') oldLines++;
      if (op !== 'delete') newLines++;
      lines.push((op === 'equal' ? ' ' : op === 'delete' ? '-' : '+') + line);
    }
    hunks.push({
      oldStart: oldFrom + (oldLines === 0 ? 0 : 1),
      oldLines,
      newStart: newFrom + (newLines === 0 ? 0 : 1),
      newLines,
      lines,
    });
    oldCursor = oldFrom + oldLines;
    newCursor = newFrom + newLines;
    i = end;
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  const result = [];
  let oldCursor = 0;
  if (!Array.isArray(hunks)) throw new Error('hunk 0 does not apply');
  for (let index = 0; index < hunks.length; index++) {
    const hunk = hunks[index];
    const fail = () => { throw new Error(`hunk ${index} does not apply`); };
    if (!hunk || !Array.isArray(hunk.lines) ||
        !Number.isSafeInteger(hunk.oldStart) || hunk.oldStart < 0 ||
        !Number.isSafeInteger(hunk.newStart) || hunk.newStart < 0 ||
        !Number.isSafeInteger(hunk.oldLines) || hunk.oldLines < 0 ||
        !Number.isSafeInteger(hunk.newLines) || hunk.newLines < 0) {
      fail();
    }
    const oldFrom = hunk.oldStart - (hunk.oldLines === 0 ? 0 : 1);
    const newFrom = hunk.newStart - (hunk.newLines === 0 ? 0 : 1);
    if (oldFrom < oldCursor || oldFrom > a.length ||
        hunk.oldLines > a.length - oldFrom ||
        newFrom !== result.length + oldFrom - oldCursor) {
      fail();
    }
    while (oldCursor < oldFrom) result.push(a[oldCursor++]);
    let oldLines = 0;
    let newLines = 0;
    for (const entry of hunk.lines) {
      if (typeof entry !== 'string' || entry.length === 0) fail();
      const prefix = entry[0];
      const line = entry.slice(1);
      if (prefix !== ' ' && prefix !== '-' && prefix !== '+') fail();
      if (prefix !== '+') {
        if (oldLines >= hunk.oldLines || a[oldCursor] !== line) fail();
        oldCursor++;
        oldLines++;
      }
      if (prefix !== '-') {
        result.push(line);
        newLines++;
      }
    }
    if (oldLines !== hunk.oldLines || newLines !== hunk.newLines) fail();
  }
  while (oldCursor < a.length) result.push(a[oldCursor++]);
  return result;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

