'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = new Array(b.length + 1).fill(0);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const previous = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = previous;
    }
  }
  return row[b.length];
}

function check(a, b) {
  const script = diffLines(a, b);
  assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
  assert.equal(script.filter(e => e.op !== 'equal').length,
    a.length + b.length - 2 * lcs(a, b));
  let inserted = false;
  for (const entry of script) {
    assert.ok(['equal', 'delete', 'insert'].includes(entry.op));
    if (entry.op === 'equal') inserted = false;
    else if (entry.op === 'insert') inserted = true;
    else assert.equal(inserted, false);
  }
  assert.deepEqual(diffLines(a, b), script);
  for (let context = 0; context <= 3; context++) {
    const hunks = unifiedHunks(a, b, { context });
    assert.deepEqual(applyHunks(a, hunks), b);
    if (a.length === b.length && a.every((line, i) => line === b[i])) {
      assert.deepEqual(hunks, []);
    }
  }
}

test('exhaustive minimal scripts and roundtrips with repetitive and empty lines', () => {
  const arrays = [Object.freeze([])];
  let level = [[]];
  for (let length = 1; length <= 4; length++) {
    level = level.flatMap(a => ['', 'a', 'b'].map(line => Object.freeze([...a, line])));
    arrays.push(...level);
  }
  for (const a of arrays) for (const b of arrays) check(a, b);
  console.log(`Checked ${arrays.length ** 2} exhaustive input pairs across four contexts`);
});

test('deterministic larger randomized repetitive cases', () => {
  let state = 1;
  const random = n => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state % n;
  };
  const alphabet = ['', 'a', 'b', 'c', '+prefix', '-prefix', ' prefix', '\r'];
  for (let i = 0; i < 1000; i++) {
    const make = () => Object.freeze(Array.from({ length: random(35) }, () => alphabet[random(alphabet.length)]));
    check(make(), make());
  }
});

test('golden hunk coordinates, context boundaries and prefix preservation', () => {
  assert.deepEqual(unifiedHunks([], ['+x', '-y', ' z'], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 3, lines: ['++x', '+-y', '+ z'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b'], [], { context: 0 }), [
    { oldStart: 1, oldLines: 2, newStart: 0, newLines: 0, lines: ['-a', '-b'] },
  ]);
  assert.deepEqual(unifiedHunks(['a'], ['a', 'b'], { context: 0 }), [
    { oldStart: 1, oldLines: 0, newStart: 2, newLines: 1, lines: ['+b'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b'], ['a'], { context: 0 }), [
    { oldStart: 2, oldLines: 1, newStart: 1, newLines: 0, lines: ['-b'] },
  ]);
  const a = ['head', 'old1', 'c1', 'c2', 'old2', 'tail'];
  const b = ['head', 'new1', 'c1', 'c2', 'new2', 'tail'];
  assert.deepEqual(unifiedHunks(a, b, { context: 1 }), [
    { oldStart: 1, oldLines: 6, newStart: 1, newLines: 6,
      lines: [' head', '-old1', '+new1', ' c1', ' c2', '-old2', '+new2', ' tail'] },
  ]);
  a.splice(4, 0, 'c3');
  b.splice(4, 0, 'c3');
  assert.deepEqual(unifiedHunks(a, b, { context: 1 }), [
    { oldStart: 1, oldLines: 3, newStart: 1, newLines: 3, lines: [' head', '-old1', '+new1', ' c1'] },
    { oldStart: 5, oldLines: 3, newStart: 5, newLines: 3, lines: [' c3', '-old2', '+new2', ' tail'] },
  ]);
  assert.deepEqual(unifiedHunks(['h', 'a', 'b', 'c', 'd', 't'], ['h', 'A', 'b', 'c', 'd', 't']), [
    { oldStart: 1, oldLines: 5, newStart: 1, newLines: 5, lines: [' h', '-a', '+A', ' b', ' c', ' d'] },
  ]);
  const prefixed = Object.freeze(['+a', '-b', ' c', '', 'tail']);
  const hunks = unifiedHunks(prefixed, ['+A', '-B', ' C', '', 'tail']);
  for (const hunk of hunks) { Object.freeze(hunk.lines); Object.freeze(hunk); }
  Object.freeze(hunks);
  assert.deepEqual(applyHunks(prefixed, hunks), ['+A', '-B', ' C', '', 'tail']);
  const copy = applyHunks(prefixed, []);
  assert.deepEqual(copy, prefixed);
  assert.notEqual(copy, prefixed);
});

test('application offsets and rejection of malformed/nonapplicable hunks', () => {
  const a = Object.freeze(['a', 'b', 'c', 'd']);
  const first = Object.freeze({ oldStart: 1, oldLines: 0, newStart: 2, newLines: 1,
    lines: Object.freeze(['+x']) });
  const second = Object.freeze({ oldStart: 3, oldLines: 1, newStart: 3, newLines: 0,
    lines: Object.freeze(['-c']) });
  assert.deepEqual(applyHunks(a, Object.freeze([first, second])), ['a', 'x', 'b', 'd']);
  const replacement = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  const bad = [null, {}, { ...replacement, oldStart: 0 }, { ...replacement, newStart: 0 },
    { ...replacement, oldStart: 10 }, { ...replacement, newStart: 10 },
    { ...replacement, oldLines: -1 }, { ...replacement, newLines: -1 },
    { ...replacement, oldStart: 1.5 }, { ...replacement, newStart: NaN },
    { ...replacement, oldLines: Infinity }, { ...replacement, newLines: '1' },
    { ...replacement, oldLines: 2 }, { ...replacement, newLines: 2 },
    { ...replacement, lines: null }, { ...replacement, lines: ['-wrong', '+B'] },
    { ...replacement, lines: [' wrong'] }, { ...replacement, lines: [''] },
    { ...replacement, lines: [null] }, { ...replacement, lines: ['?b'] },
    { ...replacement, lines: ['-b', '-c', '+B'] }];
  for (const hunk of bad) assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [replacement, replacement]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [first, { ...second, newStart: 2 }]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [second, first]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, null), /hunk 0 does not apply/);
});

test('small changes to 20,000 lines, including repetitive input', () => {
  for (const repetitive of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repetitive ? 'repeat' : `line ${i}`);
    const b = a.slice();
    b.splice(100, 1, 'replacement');
    b.splice(10000, 0, '+inserted', '');
    b.splice(18000, 2);
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const patched = applyHunks(a, hunks);
    const elapsed = performance.now() - start;
    assert.deepEqual(patched, b);
    assert.equal(script.filter(e => e.op !== 'equal').length, 6);
    assert.ok(elapsed < 500, `20,000-line roundtrip took ${elapsed}ms`);
    console.log(`20,000-line ${repetitive ? 'repetitive' : 'unique'} diff + hunks + apply: ${elapsed.toFixed(2)}ms`);
  }
  const a = Array.from({ length: 20000 }, (_, i) => `line ${i}`);
  assert.deepEqual(unifiedHunks(a, a), []);
  assert.deepEqual(applyHunks([], unifiedHunks([], a)), a);
  assert.deepEqual(applyHunks(a, unifiedHunks(a, [])), []);
});

